def order_ell_point(E, ell):
    m = E.order() // ell
    while True:
        P = m * E.random_point()
        if P != E(_sage_const_0 ):
            return P


def ell_isogeny_step(E, ell):
    P = order_ell_point(E, ell)
    assert P.order() == ell
    return E.isogeny(P).codomain()


def csidh_action(E, primes, exponents):
    # Positive e_i: step e_i times via the rational point of order ell_i
    # on the current curve. Negative e_i would instead step via the
    # twist (not needed for this challenge's all-positive vector).
    for ell, e in zip(primes, exponents):
        if e < _sage_const_0 :
            raise NotImplementedError("negative exponents need the twist direction")
        for _ in range(e):
            E = ell_isogeny_step(E, ell)
    return E


def montgomery_A(E):
    Emont = E.montgomery_model()
    _, A, _, _, _ = Emont.a_invariants()
    return A


primes = [_sage_const_3 , _sage_const_5 , _sage_const_7 ]
